mapper.sql:
ei.item_type = 'EVENT' AND ei.approval_status = 'APPROVED' AND ei.visibility_status = 'VISIBLE' AND ei.deleted_at IS NULL AND e.deleted_at IS NULL AND e.status IN ('SCHEDULED', 'ONGOING')
AND e.event_kind IN
#{eventKind}
AND e.region1 IN
#{region1}
AND e.region2 IN
#{region2}
AND e.region3 IN
#{region3}
AND ( e.title LIKE CONCAT('%', #{request.keyword}, '%') OR e.subtitle LIKE CONCAT('%', #{request.keyword}, '%') OR e.description LIKE CONCAT('%', #{request.keyword}, '%') )
AND e.status = 'ONGOING'
AND e.status = 'SCHEDULED'
AND e.start_date <= DATE_ADD( CURRENT_DATE(), INTERVAL (8 - DAYOFWEEK(CURRENT_DATE())) DAY ) AND (e.end_date IS NULL OR e.end_date >= DATE_ADD( CURRENT_DATE(), INTERVAL (7 - DAYOFWEEK(CURRENT_DATE())) DAY ))
AND e.start_date <= LAST_DAY(CURRENT_DATE()) AND (e.end_date IS NULL OR e.end_date >= DATE_FORMAT( CURRENT_DATE(), '%Y-%m-01' ))
AND (e.end_date IS NULL OR e.end_date >= #{request.startDate})
AND e.start_date <= #{request.endDate}
AND e.is_free = TRUE
AND e.open_weekend = TRUE
AND e.opens_late = TRUE
AND JSON_UNQUOTE(JSON_EXTRACT(e.pre_reservation, '$.has')) = 'true'
AND e.is_experience = TRUE
AND e.has_photo_zone = TRUE
AND EXISTS ( SELECT 1 FROM event_activity filter_ea JOIN activity filter_a ON filter_a.activity_id = filter_ea.activity_id WHERE filter_ea.event_id = e.event_id AND filter_ea.deleted_at IS NULL AND filter_a.deleted_at IS NULL AND filter_a.sector_id IN
#{sectorId}
)
AND EXISTS ( SELECT 1 FROM event_activity filter_ea WHERE filter_ea.event_id = e.event_id AND filter_ea.deleted_at IS NULL AND filter_ea.activity_id IN
#{activityId}
)
AND EXISTS ( SELECT 1 FROM explore_item_likes saved_like WHERE saved_like.item_id = ei.item_id AND saved_like.member_id = #{memberId} AND saved_like.deleted_at IS NULL )
